Object.assign(window.deepArticles,{
"politics-of-japan":japanPoliticsArticle({title:"Politics of Japan",category:"Politics by country",infoboxKicker:"Managed parliamentary government under imperial sanction",lead:"The politics of postwar Japan combine imperial sovereignty, cabinet administration, a functioning but bounded Imperial Diet, recognized conservative factions and independents, ministerial bureaucracy, military influence, corporate bargaining, and extensive police supervision. The Lisbon victory ends emergency mobilization without producing either occupation democracy or a unified revolutionary party-state.",canon:"Japan is managed-parliamentary and authoritarian after Lisbon. The Diet matters for budgets, patronage, petitions, regional interests, corporate competition, and criticism of administrative incompetence, while the Emperor, supreme command, and fundamental imperial settlement remain outside ordinary parliamentary control. Exact electoral law, party labels, seat totals, and institutional reorganizations remain open.",sections:[
{id:"settlement",title:"Post-Lisbon settlement",html:"<p>Tōjō leaves the premiership with honor in 1947. Yonai demobilizes the wartime machine, Shigemitsu constitutionalizes graded sovereignty, and Kishi consolidates developmental government through ministries, banks, and corporate houses.</p>"},
{id:"emperor",title:"The Emperor",html:"<p>The <a href='emperor-in-postwar-japanese-politics.html'>Emperor</a> sanctions cabinets, treaties, high appointments, and decisions reserved for Imperial Conference. He is neither daily executive nor powerless ornament.</p>"},
{id:"cabinet",title:"Cabinet government",html:"<p>The prime minister and Cabinet conduct ordinary government: budgets, legislation, appointments, economic plans, policing, diplomacy, and administration. Their authority depends upon parliamentary supply, bureaucratic execution, court confidence, and accommodation with the services.</p>"},
{id:"diet",title:"Imperial Diet",html:"<p>The <a href='imperial-diet-postwar-japan.html'>Imperial Diet</a> again becomes a working arena for appropriation, law, petitions, constituency service, administrative criticism, and bargaining among regions and corporate interests.</p>"},
{id:"politics",title:"Parties and factions",html:"<p>The wartime association recedes into an electoral cartel. Recognized factions, noncommunist constitutional conservatives, business independents, and local machines compete without challenging the imperial constitution.</p>"},
{id:"administration",title:"Bureaucracy and police",html:"<p>The ministries retain extraordinary continuity and expertise. The <a href='home-ministry-police-postwar-japan.html'>Home Ministry and police</a> supervise local government, elections, public order, associations, and political boundaries.</p>"},
{id:"interests",title:"Services, court, and corporations",html:"<p>Army and Navy elders, court advisers, economic ministries, zaibatsu, banks, prefectures, and parliamentary brokers possess different forms of veto and access. No single institution commands the entire state.</p>"},
{id:"limits",title:"Opposition and limits",html:"<p>Criticism of corruption, taxes, contractors, shortages, or administrative incompetence can be public. Communist, republican, anti-imperial, violent separatist, and colonial-independence organization remains illegal or heavily suppressed.</p>"}],
related:[{href:"postwar-governments-of-japan.html",kicker:"Cabinet chronology",label:"Postwar Governments of Japan"},{href:"emperor-in-postwar-japanese-politics.html",kicker:"Sovereign authority",label:"Emperor in Postwar Politics"},{href:"imperial-diet-postwar-japan.html",kicker:"Legislature",label:"Imperial Diet"},{href:"political-parties-factions-postwar-japan.html",kicker:"Recognized competition",label:"Political Parties and Factions"},{href:"home-ministry-police-postwar-japan.html",kicker:"Internal administration",label:"Home Ministry and Police"},{href:"japan.html",kicker:"Country article",label:"Empire of Japan"}],facts:[["Form of government","Managed parliamentary authoritarianism"],["Head of state","Emperor"],["Ordinary executive","Prime minister and Cabinet"],["Legislature","Imperial Diet"],["Legal competition","Recognized factions and independents"],["Reserved questions","Throne, supreme command, imperial settlement"],["Administrative center","Ministerial bureaucracy"],["Detailed electoral system","Open"]]}),

"emperor-in-postwar-japanese-politics":japanPoliticsArticle({title:"Emperor in Postwar Japanese Politics",infoboxKicker:"Sanctioning and mediating sovereign",lead:"The Emperor in postwar Japanese politics is the sanctioning sovereign above cabinet competition and the principal constitutional mediator when the court, armed services, ministries, or Diet cannot settle a reserved question. Imperial authority is strongest at moments of transition and strategic choice, while daily industrial, fiscal, and administrative government belongs to ministers.",canon:"Hirohito's sanction of the Limited-War Directive, his role in the 1947 cabinet transition, the absence of an occupation constitution, and Akihito's court sponsorship of the Tehran Concord are established. The Emperor is neither parliamentary executive nor powerless ornament. The frequency and content of private audiences remain open.",sections:[
{id:"position",title:"Constitutional position",html:"<p>The throne remains the source of formal sanction in a victorious empire that has not adopted the historical occupation constitution. Japan remains oligarchic and administrative rather than a personal imperial dictatorship.</p>"},
{id:"sanction",title:"Sanction and promulgation",html:"<p>Cabinet appointments, treaties, major rescripts, high commands, and reserved strategic decisions receive imperial sanction. Ordinary laws and budgets move through cabinet and Diet procedure before promulgation.</p>"},
{id:"conference",title:"Imperial Conference",html:"<p>The Imperial Conference settles exceptional questions joining government and supreme command. Hirohito's approval of war against Britain and the Netherlands while excluding deliberate American targets is the defining example.</p>"},
{id:"transition",title:"The transition of 1947",html:"<p>Tōjō is promoted out of government rather than repudiated. The throne protects Army honor while authorizing Yonai to convert victory mobilization into settlement administration.</p>"},
{id:"audiences",title:"Audiences and information",html:"<p>Ministers, senior statesmen, service chiefs, and court officials brief the Emperor. Questions, requests for reconsideration, and choice among submitted alternatives can shape outcomes without making the sovereign the author of every policy.</p>"},
{id:"diet",title:"Relationship with Cabinet and Diet",html:"<p>The Emperor appoints under constitutional form but does not draft routine budgets or manage ministries. The Diet cannot treat the throne or fundamental imperial settlement as ordinary partisan questions.</p>"},
{id:"hirohito",title:"Hirohito's later reign",html:"<p><a href='hirohito.html'>Hirohito</a> remains cautious, procedural, and sacred. Imperial tours, industrial exhibitions, military reviews, and diplomatic receptions represent an order whose daily operation is increasingly technocratic.</p>"},
{id:"akihito",title:"Akihito and public integration",html:"<p><a href='akihito.html'>Akihito</a> is trained as envoy, officer-aristocrat, scientific patron, and public face of Asian empire. By Tehran he supplies court sponsorship while Nakasone conducts negotiation as executive.</p>"}],
related:[{href:"hirohito.html",kicker:"Shōwa sovereign",label:"Hirohito"},{href:"akihito.html",kicker:"Successor",label:"Akihito"},{href:"imperial-limited-war-directive.html",kicker:"Defining sanction",label:"Imperial Limited-War Directive"},{href:"imperial-diet-postwar-japan.html",kicker:"Constitutional legislature",label:"Imperial Diet"},{href:"postwar-governments-of-japan.html",kicker:"Cabinet sequence",label:"Postwar Governments of Japan"}],facts:[["Office","Emperor of Japan"],["Political character","Sanctioning and mediating sovereign"],["Daily executive","Cabinet"],["Exceptional forum","Imperial Conference"],["Defining wartime act","Limited-War Directive"],["Defining postwar act","1947 cabinet transition"],["1985 role","Court sponsorship of Tehran"],["Private interventions","Open"]]}),

"imperial-diet-postwar-japan":japanPoliticsArticle({title:"Imperial Diet in Postwar Japan",infoboxKicker:"Bounded legislature of the victorious empire",lead:"The Imperial Diet in postwar Japan is a functioning legislature within a restricted constitutional order. Its lower house matters for supply, law, constituency representation, petitions, patronage, and criticism of administration. It does not possess parliamentary supremacy over the Emperor, supreme command, or the fundamental settlement of empire.",canon:"The post-Lisbon House of Representatives regains importance for budgets, patronage, petitions, regional interests, corporate competition, and administrative criticism. More than eighty percent of seats in the historical 1942 election went to approved candidates while critics could still win; this informs, but does not fix, the later system. Chamber composition, franchise changes, electoral districts, and exact powers remain open.",sections:[
{id:"survival",title:"Survival after victory",html:"<p>Japan's legislature is not abolished by a revolutionary party and is not remade by foreign occupation. Yonai's demobilization gives parliamentary procedure renewed value as emergency orders and requisitions recede.</p>"},
{id:"houses",title:"Chambers",html:"<p>The House of Representatives supplies the principal electoral arena. The precise postwar composition and reform of the upper chamber remain to be established rather than imported from the historical 1947 constitution.</p>"},
{id:"supply",title:"Budgets and law",html:"<p>Members debate appropriations, taxes, reconstruction, transport, welfare, industrial projects, and administrative statutes. Refusal or delay of supply can inconvenience a cabinet even when it cannot overturn the imperial order.</p>"},
{id:"petitions",title:"Petitions and constituencies",html:"<p>Regional infrastructure, prices, land, veterans, schools, company conduct, and local appointments move through members as petitions and bargaining claims.</p>"},
{id:"scrutiny",title:"Administrative scrutiny",html:"<p>Questions, committees, and public debate expose waste, corruption, procurement failures, and incompetent execution. Miki's post-Biak review of civilian space spending shows the later reach of scrutiny.</p>"},
{id:"economic-oversight",title:"Oversight of the imperial economy",html:"<!-- altwwii-writer-block:start id=wb-j-20260816-d4q8m writer=j kind=analysis created=2026-08-16T11:50:46-06:00 --><p>Diet scrutiny gives divided imperial administration a national forum. Members can compare Finance Ministry appropriations, Economic Board priorities, Development Bank exposure, sector-ministry reports, company performance, and petitions from affected constituencies. Supply votes can require accounts, limit a new guarantee, condition recapitalization, or force a minister to defend why strategic capacity should remain outside an ordinary profit test.</p><p>The representation boundary remains constitutional. Chōsen, Taiwan, Karafuto, the Ryukyus, and incorporated Pacific territories belong to Japan and can raise claims through Japanese elections, members, and petitions even where access is unequal. Thailand, the Philippines, Manchukuo, National China, and other associated states do not vote in the Diet. Their governments bargain through the Economic Board, bilateral ministries, finance, concessions, and diplomacy. Parliamentary oversight of Tokyo therefore does not replace center-periphery negotiation among formally separate states.</p><p>After preservationism, scrutiny increasingly concerned whether a program maintained employment, transport, relief, training, and lawful administration. Cultural grants and regional institutions remained proper budget subjects, but cultural recognition did not automatically command a restored government or separate nationality. The Diet itself remained bounded by police regulation, corporate money, managed candidacy, and the exclusion of anti-imperial platforms. Its ability to expose failure did not make the wider settlement politically equal.</p><!-- altwwii-writer-block:end -->"},
{id:"factions",title:"Factions and brokerage",html:"<p>Recognized groupings organize candidates, committee work, ministries, and patronage. Corporate and bureaucratic interests seek parliamentary brokers rather than rule only through direct decree.</p>"},
{id:"boundaries",title:"Constitutional boundaries",html:"<p>The Diet does not control the throne, supreme command, or the existence of empire as ordinary party questions. Republican and anti-imperial platforms remain outside lawful competition.</p>"},
{id:"unknowns",title:"Unsettled institutional record",html:"<p>The archive does not yet fix postwar electoral statutes, district maps, membership totals, upper-house reform, election dates, or stable party seat counts.</p>"}],
related:[{href:"politics-of-japan.html",kicker:"Political system",label:"Politics of Japan"},{href:"political-parties-factions-postwar-japan.html",kicker:"Legislative organization",label:"Political Parties and Factions"},{href:"imperial-rule-assistance-association-after-victory.html",kicker:"Wartime inheritance",label:"Imperial Rule Assistance Association after Victory"},{href:"takeo-miki.html",kicker:"Scrutiny after Biak",label:"Takeo Miki"},{href:"japanese-ministry-of-finance.html",kicker:"Budgetary gatekeeper",label:"Ministry of Finance"}],facts:[["Legislature","Imperial Diet"],["Electoral chamber","House of Representatives"],["Principal powers","Law, supply, petition, scrutiny"],["Political function","Regional and corporate brokerage"],["Reserved from ordinary control","Throne and supreme command"],["Postwar electoral statute","Open"],["Upper chamber settlement","Open"],["Seat chronology","Open"]]}),

"political-parties-factions-postwar-japan":japanPoliticsArticle({title:"Political Parties and Factions in Postwar Japan",infoboxKicker:"Recognized competition inside imperial limits",lead:"Political parties and factions in postwar Japan re-emerge from the wartime mass association as a regulated field of conservative, bureaucratic, business, regional, and independent competition. They contest administration and the distribution of development without receiving a lawful route to republicanism, communism, colonial independence, or repudiation of Japanese imperial primacy.",canon:"The wartime association becomes an electoral cartel; recognized factions gradually reappear; noncommunist constitutional conservatives and business independents are tolerated; anti-imperial, communist, republican, and colonial-independence politics are illegal or heavily suppressed. Exact party names, mergers, platforms, colors, leaders, and election results remain open.",sections:[
{id:"reappearance",title:"Reappearance after Lisbon",html:"<p>Demobilization removes much of the association's control over neighborhood labor and production. Its Diet organization survives while coherent tendencies begin operating as recognizable factions.</p>"},
{id:"families",title:"Political families",html:"<p>Likely alignments include bureaucratic developmentalists, imperial-association conservatives, business independents, provincial brokers, service-linked nationalists, and restrained constitutional critics. These are analytical families, not fixed party names.</p>"},
{id:"organization",title:"Organization",html:"<p>Factions recruit candidates, raise funds, negotiate endorsements, divide committee posts, and connect constituencies with ministries and corporate houses.</p>"},
{id:"competition",title:"Issues of competition",html:"<p>Legal disagreement concerns taxation, prices, infrastructure, agricultural protection, corruption, social provision, corporate privilege, procurement, local autonomy, and the pace of imperial development.</p>"},
{id:"business",title:"Business and bureaucracy",html:"<p>Zaibatsu, banks, trade associations, ministries, and prefectural networks sponsor rival policies and candidates. Influence is mediated through access, credit, expertise, and patronage rather than one command chain.</p>"},
{id:"independents",title:"Independents and critics",html:"<p>Constitutional conservatives and business independents can win office when they accept the throne and imperial settlement. Their existence distinguishes the order from a monopolistic mass party.</p>"},
{id:"prohibitions",title:"Prohibited organization",html:"<p>Communist, republican, anti-imperial, violent separatist, and colonial-independence organization is illegal or heavily suppressed. Police distinguish permitted administrative criticism from attacks on protected foundations.</p>"},
{id:"record",title:"Open party chronology",html:"<p>No canonical list yet fixes the postwar parties, their legal succession, leadership, symbols, colors, district machines, coalitions, or election-by-election strength.</p>"}],
related:[{href:"imperial-rule-assistance-association-after-victory.html",kicker:"Organizational predecessor",label:"Imperial Rule Assistance Association after Victory"},{href:"imperial-diet-postwar-japan.html",kicker:"Legislative arena",label:"Imperial Diet"},{href:"political-opposition-postwar-japan.html",kicker:"Permitted and prohibited speech",label:"Political Opposition"},{href:"corporate-politics-geacps.html",kicker:"Imperial political economy",label:"Corporate Politics in the GEACPS"},{href:"postwar-governments-of-japan.html",kicker:"Cabinet outcomes",label:"Postwar Governments of Japan"}],facts:[["Postwar form","Recognized factions and independents"],["Wartime inheritance","Government electoral cartel"],["Permitted tendency","Noncommunist constitutional conservatism"],["Common issues","Budgets, patronage, administration, development"],["Major patrons","Business, ministries, regions, associations"],["Prohibited politics","Communist, republican, anti-imperial"],["Canonical party names","Open"],["Election results","Open"]]}),

"imperial-rule-assistance-association-after-victory":japanPoliticsArticle({title:"Imperial Rule Assistance Association after Victory",infoboxKicker:"Wartime mass organization in demobilization",lead:"After the Lisbon victory, the Imperial Rule Assistance Association survives long enough to organize political continuity but fails to become a Japanese equivalent of the German Nazi Party. Its neighborhood mobilization and production functions contract, its Diet machinery becomes a government electoral cartel, and recognized factions and independents gradually reappear inside a still authoritarian order.",canon:"Temporary survival, loss of direct neighborhood and war-production control, conversion of the Diet organization into an electoral cartel, gradual factional reappearance, and failure to become an autonomous revolutionary party are established. A formal dissolution date, successor legal name, property settlement, membership figures, and complete organizational chart remain open.",sections:[
{id:"wartime",title:"Wartime character",html:"<p>The association was created from above to integrate parties and civic bodies. It never acquired the autonomous mass power or ideological cohesion of Germany's ruling party.</p>"},
{id:"lisbon",title:"Victory without revolution",html:"<p>Victory strengthens the throne, services, bureaucracy, and state. It does not give the association an independent claim to rule over those institutions.</p>"},
{id:"demobilization",title:"Demobilization",html:"<p>Yonai's settlement removes direct control over neighborhood mobilization, ration work, and war production as soldiers return and civilian shipping, budgets, and local government resume.</p>"},
{id:"cartel",title:"Electoral cartel",html:"<p>The surviving Diet organization endorses candidates, manages access, and protects governmental majorities. It is better understood as an official electoral framework than as a total party commanding every institution.</p>"},
{id:"factions",title:"Factional re-emergence",html:"<p>Imperial conservatives, bureaucratic developers, business independents, regional brokers, and constitutional critics become increasingly legible within or beside the cartel.</p>"},
{id:"state",title:"Relationship to the state",html:"<p>The association depends upon the Home Ministry, police, Cabinet, and bureaucracy. It does not monopolize appointments, supreme command, finance, or imperial access.</p>"},
{id:"limits",title:"Political limits",html:"<p>Opening does not legalize communism, republicanism, anti-imperial organization, or colonial independence. Elections operate inside a protected constitutional settlement.</p>"},
{id:"unknowns",title:"Unsettled succession",html:"<p>Whether the cartel keeps the wartime name, divides formally, or yields to successor associations is deliberately unresolved pending a full party chronology.</p>"}],
related:[{href:"political-parties-factions-postwar-japan.html",kicker:"Successor competition",label:"Political Parties and Factions"},{href:"imperial-diet-postwar-japan.html",kicker:"Electoral arena",label:"Imperial Diet"},{href:"home-ministry-police-postwar-japan.html",kicker:"Administrative supervisor",label:"Home Ministry and Police"},{href:"hideki-tojo.html",kicker:"Victory Cabinet",label:"Hideki Tōjō"},{href:"mitsumasa-yonai.html",kicker:"Demobilization",label:"Mitsumasa Yonai"}],facts:[["Wartime type","Government-created integration organization"],["Post-Lisbon survival","Temporary"],["Neighborhood mobilization","Reduced"],["Diet machinery","Government electoral cartel"],["Autonomous party power","Limited"],["Recognized competition","Gradually restored"],["Formal dissolution date","Open"],["Successor organizations","Open"]]}),

"home-ministry-police-postwar-japan":japanPoliticsArticle({title:"Home Ministry and Police in Postwar Japan",infoboxKicker:"Internal administration and protected political order",lead:"The Home Ministry and police in postwar Japan connect central government to prefectures, elections, associations, public order, political surveillance, and local administration. Victory prevents the historical occupation-era dismantling of the prewar internal state. Demobilization narrows wartime emergency functions, but police power remains central to defining the boundary between lawful criticism and prohibited opposition.",canon:"The Home Ministry and police bureaucracy are established members of the postwar governing coalition, and communist, republican, anti-imperial, and colonial-independence politics remain illegal or heavily suppressed. Exact ministry organization, police centralization, special-branch names, statutes, and reform dates remain open. This article does not assume an unchanged prewar chart.",sections:[
{id:"continuity",title:"Continuity after victory",html:"<p>There is no foreign purge or occupation abolition. Experienced officials retain local-government, election, association, and security functions while adapting from mobilization to developmental administration.</p>"},
{id:"local",title:"Prefectures and municipalities",html:"<p>The ministry supervises central-local relations, prefectural administration, appointments or approvals where retained, elections, and the transmission of policy into municipal government.</p>"},
{id:"territorial-boundary",title:"Territorial reach",html:"<!-- altwwii-writer-block:start id=wb-j-20260816-g9r1y writer=j kind=analysis created=2026-08-16T13:03:26-06:00 --><p>The ministry's domestic chain extended through prefectures, regional governments, and municipalities in integral Japan. In Chōsen, Taiwan, Karafuto, the Ryukyus, and incorporated Pacific territories it coordinated the officials responsible for elections, associations, public order, local administration, and emergency response under Japanese sovereignty. Administrative forms and access to senior office could differ even though the nationality boundary did not.</p><p>Associated and protected states retained their own interior ministries, police forces, local governments, and nationality systems.<sup class='canon-note' data-provenance='a'>[a]</sup> Tokyo influenced them through diplomatic agreements, security missions, intelligence liaison, corporate and transport arrangements, and conditions attached to Japanese support. The Home Ministry could not lawfully administer an associated state as a Japanese prefecture. Bases, company districts, rail corridors, and treaty residents instead required defined relations with host authorities.</p><p>Post-preservationist officials judged local administration by its ability to maintain law, conduct elections, move relief, keep records, protect transport, and sustain ordinary employment. Cultural authenticity alone did not justify replacing an integrated office with a reconstructed historical authority. The standard favored continuity in jurisdictions formed through settlement, police repression, land seizure, and metropolitan-language administration. Efficient government could preserve coercive boundaries as readily as it preserved public services.</p><!-- altwwii-writer-block:end -->"},
{id:"police",title:"Police administration",html:"<p>Ordinary forces handle crime, traffic, public gatherings, labor disorder, records, and local security. The balance between national direction and prefectural command is not yet fixed.</p>"},
{id:"political",title:"Political police",html:"<p>Specialized officers monitor communist, republican, anti-imperial, separatist, and violent organizations, as well as foreign influence in associations, universities, publishing, and strategic industry.</p>"},
{id:"elections",title:"Elections and associations",html:"<p>Registration, candidate eligibility, meetings, campaign order, civic bodies, and the remains of wartime neighborhood organization give internal administrators substantial influence over political competition.</p>"},
{id:"labor",title:"Labor and universities",html:"<p>Police distinguish economic grievance and bounded protest from independent class organization or ideological opposition to protected institutions. Exact strike and campus rules remain open.</p>"},
{id:"services",title:"Military and intelligence boundaries",html:"<p>Domestic police coexist with service security, defense councils, and specialized intelligence. Jurisdiction over civilians, veterans, arsenals, and imperial installations is negotiated rather than presumed.</p>"},
{id:"reform",title:"Unsettled postwar reform",html:"<p>The archive has not decided whether the Home Ministry keeps its name and full prewar scope, sheds functions to specialist ministries, or develops a separate national police agency.</p>"}],
related:[{href:"politics-of-japan.html",kicker:"Political system",label:"Politics of Japan"},{href:"political-opposition-postwar-japan.html",kicker:"Political boundary",label:"Political Opposition"},{href:"imperial-rule-assistance-association-after-victory.html",kicker:"Association supervision",label:"Imperial Rule Assistance Association after Victory"},{href:"police-intelligence-geacps.html",kicker:"Sphere comparison",label:"Police and Intelligence in the GEACPS"},{href:"japanese-military-police-abroad.html",kicker:"External military jurisdiction",label:"Japanese Military Police abroad"}],facts:[["Primary sphere","Internal administration"],["Core functions","Local government, elections, police, associations"],["Postwar status","Institutional continuity with demobilization"],["Political security","Central function"],["Ordinary policing","Crime, traffic, gatherings, public order"],["Military relationship","Separate but overlapping jurisdiction"],["Final ministry structure","Open"],["Police centralization","Open"]]}),

"political-opposition-postwar-japan":japanPoliticsArticle({title:"Political Opposition in Postwar Japan",infoboxKicker:"Permitted criticism and protected conclusions",lead:"Political opposition in postwar Japan operates within a sharp distinction between criticism of government performance and rejection of the imperial order. Legislators, newspapers, professional bodies, local interests, and recognized associations can attack corruption, waste, corporate privilege, taxes, shortages, or administrative brutality. Communist, republican, anti-imperial, violent separatist, and colonial-independence organization remains illegal or heavily suppressed.",canon:"Noncommunist constitutional conservatives and business independents are tolerated; administrative criticism has a parliamentary role; anti-imperial, communist, republican, and colonial-independence politics remain illegal or heavily suppressed. The exact press law, censorship offices, prison system, amnesties, and major opposition movements remain open.",sections:[
{id:"distinction",title:"The governing distinction",html:"<p>The system protects conclusions more closely than every argument. A critic may claim that a ministry, contractor, police force, or governor has betrayed imperial duty; a movement may not lawfully deny the throne or Japan's legitimate imperial office.</p>"},
{id:"lawful",title:"Lawful criticism",html:"<p>Budgets, taxes, procurement, corruption, shortages, pollution, welfare, local autonomy, corporate privilege, and administrative incompetence can become electoral and journalistic questions.</p>"},
{id:"venues",title:"Venues",html:"<p>The Diet, petitions, recognized newspapers, professional associations, company councils, universities, local assemblies, and private audiences provide unequal channels for complaint.</p>"},
{id:"prohibited",title:"Prohibited politics",html:"<p>Communist revolution, republican organization, anti-imperial politics, violent separatism, and support for colonial independence fall beyond lawful competition and attract surveillance, censorship, arrest, or exclusion.</p>"},
{id:"press",title:"Press and publication",html:"<p>Editors can expose poor administration while security authorities restrict protected strategic information, ideological organization, and material judged to attack the constitutional foundations of empire.</p>"},
{id:"universities",title:"Universities and labor",html:"<p>Students, academics, workers, and professional bodies can pursue bounded institutional grievances. The line between authorized complaint and prohibited organization remains politically contested.</p>"},
{id:"war",title:"War memory",html:"<p><a href='japanese-war-memory.html'>Public memory</a> can condemn arrogance, brutality, or incompetence when framed as departures from legitimate Japanese guardianship. The claim that Japan possesses no legitimate office in Asia remains protected from ordinary contest.</p>"},
{id:"unknowns",title:"Unsettled opposition record",html:"<p>The archive does not yet establish leading dissidents, major trials, censorship crises, underground networks, amnesties, exile communities, or changes under successive cabinets.</p>"}],
related:[{href:"political-parties-factions-postwar-japan.html",kicker:"Legal electoral field",label:"Political Parties and Factions"},{href:"home-ministry-police-postwar-japan.html",kicker:"Enforcement",label:"Home Ministry and Police"},{href:"imperial-diet-postwar-japan.html",kicker:"Parliamentary venue",label:"Imperial Diet"},{href:"japanese-war-memory.html",kicker:"Protected interpretation",label:"War Memory in Japan"},{href:"censorship-opposition-geacps.html",kicker:"Sphere comparison",label:"Censorship and Political Opposition in the GEACPS"}],facts:[["Permitted core","Administrative and policy criticism"],["Legal opposition","Constitutional conservatives and independents"],["Prohibited politics","Communist, republican, anti-imperial"],["Protected settlement","Throne and imperial primacy"],["Parliamentary venue","Imperial Diet"],["Security administrator","Home Ministry and police"],["Major opposition chronology","Open"],["Detailed censorship law","Open"]]})
});
